fn rotate(a: &[i32], offset: usize) -> Vec<i32> {
    let n = a.len();
    if n == 0 {
        return Vec::new(); // Return an empty array if input is empty
    }
    
    // Calculate the effective offset
    let effective_offset = offset % n;
    
    // Create a new vector to hold the rotated values
    let mut result = Vec::with_capacity(n);
    
    // Fill the result vector with the rotated values
    for i in 0..n {
        result.push(a[(i + effective_offset) % n]);
    }
    
    result
}